from django.core.management.base import BaseCommand
from django.db import transaction
from tasks.models import Test, Topic, Question, Answer
DATA = {'python': ('Python Basics', [('Что возвращает len([1, 2, 3])?', ['3', '2', 'Индекс последнего элемента'], 'len возвращает количество элементов.'), ('Какой тип неизменяемый?', ['tuple', 'list', 'dict'], 'Кортеж нельзя изменять после создания; список и словарь изменяемы.'), ('Как сравнить два значения?', ['a == b', 'a = b', 'a := b'], '== сравнивает значения; = присваивает, := — выражение присваивания.'), ('Какие числа даёт range(3)?', ['0, 1, 2', '1, 2, 3', '0, 1, 2, 3'], 'Правая граница range не включается; начало по умолчанию — 0.'), ('Как обработать исключение?', ['try / except', 'if / else', 'for / while'], 'except перехватывает указанные исключения из блока try.')]), 'sql': ('SQL Basics', [('Какая команда выбирает строки?', ['SELECT', 'UPDATE', 'INSERT'], 'SELECT читает данные; UPDATE и INSERT изменяют их.'), ('Что делает WHERE?', ['Фильтрует строки', 'Сортирует результат', 'Создаёт таблицу'], 'WHERE оставляет строки, удовлетворяющие условию.'), ('Как отсортировать строки?', ['ORDER BY', 'GROUP BY', 'JOIN'], 'ORDER BY задаёт порядок строк; GROUP BY группирует их.'), ('Как проверить отсутствие значения?', ['IS NULL', '= NULL', '== NULL'], 'NULL обозначает неизвестное значение; обычное равенство не заменяет IS NULL.'), ('Что гарантирует первичный ключ?', ['Уникальную идентификацию строки', 'Шифрование паролей', 'Порядок строк'], 'Первичный ключ уникален и не допускает NULL; порядок выдачи он не гарантирует.')]), 'web': ('Web / HTTP Basics', [('Какой HTTP-метод должен быть безопасным?', ['GET', 'POST', 'PATCH'], 'GET предназначен для чтения, без изменения состояния приложения.'), ('Что означает HTTP 404?', ['Ресурс не найден', 'Запрос успешен', 'Нужна авторизация'], '404 сообщает об отсутствии запрошенного ресурса.'), ('Что защищает от CSRF?', ['Проверка токена в изменяющем запросе', 'Скрытая кнопка', 'Цвет формы'], 'Сервер проверяет CSRF-токен; интерфейс не является защитой.'), ('Чем HTTPS отличается от HTTP?', ['Использует TLS для защиты транспорта', 'Всегда работает быстрее', 'Не требует сервера'], 'TLS защищает транспорт и проверяет подлинность сервера.'), ('Что означает 302?', ['Временное перенаправление', 'Ошибка базы данных', 'Постоянное удаление'], '302 отправляет клиент на адрес из заголовка Location.')]), 'testing': ('Software Testing Basics', [('Что проверяет негативный тест?', ['Поведение при некорректных данных', 'Только успешный сценарий', 'Только скорость'], 'Негативный тест проверяет обработку ошибочных входных данных или действий.'), ('Какой пример является граничным для диапазона 1–100?', ['0, 1, 100, 101', '20, 30, 40', 'Только 50'], 'Проверяют значения на границах и непосредственно за ними.'), ('Для чего нужна регрессия?', ['Проверить, не сломались ли прежние функции', 'Заменить требования', 'Скрыть найденный дефект'], 'Регрессионные проверки выявляют побочные эффекты изменений.'), ('Что нужно для воспроизводимого баг-репорта?', ['Шаги, окружение, ожидаемый и фактический результат', 'Только скриншот', 'Только название автора'], 'Эти сведения позволяют повторить проблему и сравнить поведение с ожиданиями.'), ('Что проверяет интеграционный тест?', ['Взаимодействие компонентов', 'Только одну строку кода', 'Только внешний вид'], 'Например, интеграция проверяет запрос, обработчик и сохранение в базе данных.')])}

class Command(BaseCommand):
    help = 'Добавить демонстрационные тесты; существующие материалы не перезаписываются.'

    @transaction.atomic
    def handle(self, *args, **options):
        created_count = 0
        for key, (title, questions) in DATA.items():
            test, created = Test.objects.get_or_create(demo_key=key, defaults={'title': title, 'topic': key, 'description': 'Демонстрационный учебный тест. Проверьте основы и разберите ответы.', 'difficulty': 'easy', 'time_limit': 10, 'is_active': False})
            if not created:
                continue
            section = Topic.objects.create(test=test, title=title)
            for text, answers, explanation in questions:
                question = Question.objects.create(topic=section, text=text, explanation=explanation)
                for i, answer in enumerate(answers):
                    Answer.objects.create(question=question, text=answer, is_correct=i == 0)
            test.is_active = True
            test.full_clean()
            test.save()
            created_count += 1
        self.stdout.write(self.style.SUCCESS(f'Создано демо-тестов: {created_count}. Существующие тесты сохранены.'))
